	/**
	 * Default Constructor
	 */
    public ProcedureService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ProcedureEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ProcedureRepository.class) );
		this.validator		= applicationContext.getBean(ProcedureValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Procedure
	 */
		public Procedure createProcedure( CreateProcedureCommand command ) {

		Procedure entity = new Procedure();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setProcedureId( command.getProcedureId() );
            entity.setProcedureCode( command.getProcedureCode() );
            entity.setStartDateTime( command.getStartDateTime() );
            entity.setEndDateTime( command.getEndDateTime() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Procedure {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateProcedureCommand
	 * @return		Procedure
	 */
	public Procedure updateProcedure( UpdateProcedureCommand command ) {

		Procedure entity = new Procedure();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setProcedureId( command.getProcedureId() );
            entity.setProcedureCode( command.getProcedureCode() );
            entity.setStartDateTime( command.getStartDateTime() );
            entity.setEndDateTime( command.getEndDateTime() );
            entity.setEncounter( command.getEncounter() );
            entity.setPerformer( command.getPerformer() );
            entity.setProcedureOrder( command.getProcedureOrder() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Procedure {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteProcedureCommand
	 */
	public void delete( DeleteProcedureCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getProcedureId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Procedure {0} ", id );

	}

	/**
	 * Method to retrieve the Procedure via ProcedureFetchOneSummary
	 * @param 	summary ProcedureFetchOneSummary
	 * @return 	ProcedureFetchOneResponse
	 */
	public Procedure getProcedure( ProcedureFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ProcedureFetchOneSummary arg cannot be null" );

		Procedure entity = null;
		UUID id = summary.getProcedureId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Procedure using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Procedures
	 *
	 * @return 	List<Procedure>
	 */
    public List<Procedure> getAllProcedure() {
		List<Procedure> list = projector.findAll( new FindAllProcedureQuery() );
		return list;
	}

	/**
	 * assign Encounter on Procedure
	 * @param		command AssignEncounterToProcedureCommand
	 */
	public void assignEncounter( AssignEncounterToProcedureCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignEncounter(command.getProcedureId(), command.getAssignment());

	}

	/**
	 * unAssign Encounter on Procedure
	 * @param		command UnAssignEncounterFromProcedureCommand
	 */
	public void unAssignEncounter( UnAssignEncounterFromProcedureCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignEncounter(command.getProcedureId());
	}
	
